#include <iostream>
#include <vector>
#include <algorithm>

int ArithmeticExpression(const std::vector<int>& operands) {
    std::vector<int> values;
    values.push_back(operands[0] + operands[1] + operands[2]);
    values.push_back(operands[0] * operands[1] * operands[2]);
    values.push_back((operands[0] + operands[1]) * operands[2]);
    values.push_back((operands[0] * operands[1]) + operands[2]);
    values.push_back(operands[0] + (operands[1] * operands[2]));
    values.push_back(operands[0] * (operands[1] + operands[2]));

    return *std::max_element(values.begin(), values.end());
}

